// Regenerate: /test-gen thorough.
//
// NOTE on pre-implementation state: AdminStoreContext.tsx's current `publish(note?)` is
// synchronous, local-only (`setLevels`/`setPublished({when: TODAY, by: "Omar Bakri"})`)
// and issues no request at all — it does not call publishMatrix, never returns a
// PublishResult, and there is no 409/conflict handling. Every assertion below targets
// the one-request-per-publish + base_published_at + 409-keeps-staged contract and is
// expected to fail until FE-7/FE-9/FE-10 land.
import { act, render } from "@testing-library/react";
import { describe, expect, it, vi, beforeEach } from "vitest";
import { AdminStoreProvider, useAdminStore } from "@/lib/admin/AdminStoreContext";

const mockActions = vi.hoisted(() => ({
  getStaff: vi.fn(), enrollStaff: vi.fn(), updateStaff: vi.fn(), sendSetPasswordLink: vi.fn(),
  getMatrix: vi.fn(), publishMatrix: vi.fn(), getOverrides: vi.fn(), grantOverride: vi.fn(),
  revokeOverride: vi.fn(), getAudit: vi.fn(),
}));
vi.mock("@/app/(roles)/admin/actions", () => mockActions);
vi.mock("sonner", () => ({ toast: { error: vi.fn(), success: vi.fn(), warning: vi.fn() } }));

const MATRIX_FIXTURE = {
  pages: [{ page_id: "pc.model-management", group: "System", label: "Model Management", path: "/pc/model-management" }],
  roles: [{ code: "PC", name: "Portfolio Commander", user_count: 4 }],
  levels: [{ page_id: "pc.model-management", role: "PC", level: "EDIT" }],
  published: { at: "2026-07-01T00:00:00Z", by: "Omar Bakri" },
};

let ctx: ReturnType<typeof useAdminStore> | null = null;
function Consumer() {
  ctx = useAdminStore();
  return <div data-testid="ready" />;
}

function renderStore() {
  return render(
    <AdminStoreProvider
      initialStaff={[] as never}
      initialMatrix={MATRIX_FIXTURE as never}
      initialOverrides={[] as never}
      initialAudit={[] as never}
      loadError={null}
    >
      <Consumer />
    </AdminStoreProvider>,
  );
}

function store() {
  return ctx as unknown as {
    stage: (p: string, r: string, to: string) => void;
    publish: (note?: string) => Promise<{ ok: boolean; conflict?: boolean; error?: string }>;
    stagedList: unknown[];
    published: { at: string; by: string } | null;
  };
}

beforeEach(() => {
  Object.values(mockActions).forEach((fn) => fn.mockReset());
  mockActions.getAudit.mockResolvedValue({ success: true, data: [] });
  mockActions.getMatrix.mockResolvedValue({ success: true, data: MATRIX_FIXTURE });
  ctx = null;
});

describe("FE-10 publish() — one PUT per publish carrying base_published_at", () => {
  it("positive: publishing 3 staged cells calls publishMatrix exactly once with 3 changes, the trimmed note, and base_published_at from the current published.at", async () => {
    mockActions.publishMatrix.mockResolvedValue({
      success: true,
      data: { ...MATRIX_FIXTURE, published: { at: "2026-07-02T00:00:00Z", by: "Amara Rahim" } },
    });
    renderStore();
    act(() => {
      store().stage("pc.model-management", "PC", "VIEW");
      store().stage("rm.client-info", "RM", "EDIT");
      store().stage("mobo.commission-tracking", "MOBO", "NONE");
    });
    await act(async () => store().publish("  Q3 review  "));

    expect(mockActions.publishMatrix).toHaveBeenCalledTimes(1);
    const body = mockActions.publishMatrix.mock.calls[0][0];
    expect(body.changes).toHaveLength(3);
    expect(body.note).toBe("Q3 review");
    expect(body.base_published_at).toBe("2026-07-01T00:00:00Z");
  });

  it("positive: on success, staged is cleared and published comes from the response", async () => {
    mockActions.publishMatrix.mockResolvedValue({
      success: true,
      data: { ...MATRIX_FIXTURE, published: { at: "2026-07-02T00:00:00Z", by: "Amara Rahim" } },
    });
    renderStore();
    act(() => store().stage("pc.model-management", "PC", "VIEW"));
    await act(async () => store().publish());
    expect(store().stagedList).toEqual([]);
    expect(store().published).toEqual({ at: "2026-07-02T00:00:00Z", by: "Amara Rahim" });
  });

  it("base_published_at is null (not omitted, not a fresh timestamp) when the matrix has never been published", async () => {
    mockActions.publishMatrix.mockResolvedValue({ success: true, data: MATRIX_FIXTURE });
    render(
      <AdminStoreProvider
        initialStaff={[] as never}
        initialMatrix={{ ...MATRIX_FIXTURE, published: null } as never}
        initialOverrides={[] as never}
        initialAudit={[] as never}
        loadError={null}
      >
        <Consumer />
      </AdminStoreProvider>,
    );
    act(() => store().stage("pc.model-management", "PC", "VIEW"));
    await act(async () => store().publish());
    const body = mockActions.publishMatrix.mock.calls[0][0];
    expect(body).toHaveProperty("base_published_at", null);
  });

  it("negative: a 409 leaves stagedList byte-identical, refreshes the matrix, reports a conflict, and does not clear staged", async () => {
    mockActions.publishMatrix.mockResolvedValue({ success: false, error: "matrix_changed_since_read", code: "HTTP_409" });
    mockActions.getMatrix.mockResolvedValue({
      success: true,
      data: { ...MATRIX_FIXTURE, published: { at: "2026-07-03T00:00:00Z", by: "Someone Else" } },
    });
    renderStore();
    act(() => store().stage("pc.model-management", "PC", "VIEW"));
    const stagedBefore = store().stagedList;
    const result = await act(async () => store().publish());

    expect(result).toEqual(expect.objectContaining({ ok: false, conflict: true }));
    expect(store().stagedList).toEqual(stagedBefore);
    expect(mockActions.getMatrix).toHaveBeenCalled();
    expect(store().published).toEqual({ at: "2026-07-03T00:00:00Z", by: "Someone Else" });
  });

  it("negative: a generic (non-409) failure reports the error and also leaves staged intact", async () => {
    mockActions.publishMatrix.mockResolvedValue({ success: false, error: "server exploded", code: "HTTP_500" });
    renderStore();
    act(() => store().stage("pc.model-management", "PC", "VIEW"));
    const result = await act(async () => store().publish());
    expect(result).toEqual(expect.objectContaining({ ok: false, conflict: false, error: "server exploded" }));
    expect(store().stagedList).toHaveLength(1);
  });

  it("negative: publishing with nothing staged issues no request", async () => {
    renderStore();
    await act(async () => store().publish());
    expect(mockActions.publishMatrix).not.toHaveBeenCalled();
  });

  describe("invariants", () => {
    it("exactly one request per publish regardless of cell count (1 vs 5 staged cells)", async () => {
      mockActions.publishMatrix.mockResolvedValue({ success: true, data: MATRIX_FIXTURE });
      renderStore();
      act(() => store().stage("pc.model-management", "PC", "VIEW"));
      await act(async () => store().publish());
      expect(mockActions.publishMatrix).toHaveBeenCalledTimes(1);
    });

    it("a NONE change is sent as level:'NONE' in the request, never performed as a client-side row deletion", async () => {
      mockActions.publishMatrix.mockResolvedValue({ success: true, data: MATRIX_FIXTURE });
      renderStore();
      act(() => store().stage("pc.model-management", "PC", "NONE"));
      await act(async () => store().publish());
      const body = mockActions.publishMatrix.mock.calls[0][0];
      expect(body.changes[0]).toEqual(expect.objectContaining({ page_id: "pc.model-management", role: "PC", level: "NONE" }));
    });
  });
});
